const express = require('express');
const { classify } = require('../services/orders');

const router = express.Router();

router.post('/', (req, res) => {
  const { items, priority } = req.body;
  const { tier, fee } = classify(items, Boolean(priority));
  res.json({ items, tier, fee });
});

module.exports = router;

