function classify(items, priority) {
  let tier;
  if (priority) tier = 'express';
  else if (items >= 10) tier = 'bulk';
  else tier = 'standard';
  const fee = { express: 20, bulk: 5, standard: 10 }[tier];
  return { tier, fee };
}

module.exports = { classify };

