const http = require('http');
function request(app, method, path, body) {
  return new Promise((resolve, reject) => {
    const server = app.listen(0, () => {
      const port = server.address().port;
      const data = body === undefined ? null : JSON.stringify(body);
      const headers = data
        ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
        : {};
      const req = http.request(
        { host: '127.0.0.1', port, path, method, headers, timeout: 4000 },
        (res) => {
          let buf = '';
          res.on('data', (c) => (buf += c));
          res.on('end', () => {
            server.close();
            let json = null;
            try { json = JSON.parse(buf); } catch (e) { /* non-JSON */ }
            resolve({ status: res.statusCode, body: json, raw: buf });
          });
        }
      );
      req.on('timeout', () => { req.destroy(new Error('request timed out (handler never responded)')); });
      req.on('error', (e) => { server.close(); reject(e); });
      if (data) req.write(data);
      req.end();
    });
  });
}

const assert = require('assert');
const app = require('./src/app');

async function post(items, priority) {
  return request(app, 'POST', '/orders', { items, priority: Boolean(priority) });
}

(async () => {
  let r = await post(3, false);
  assert.strictEqual(r.status, 200);
  assert.deepStrictEqual(r.body, { items: 3, tier: 'standard', fee: 10 });

  r = await post(10, false);
  assert.strictEqual(r.body.tier, 'bulk', 'items==10 is the bulk boundary');
  assert.strictEqual(r.body.fee, 5);

  r = await post(2, true);
  assert.strictEqual(r.body.tier, 'express');
  assert.strictEqual(r.body.fee, 20);

  r = await post(50, true);
  assert.strictEqual(r.body.tier, 'express', 'priority beats bulk');
  console.log('PASS');
})().catch((e) => { console.error(e); process.exit(1); });

